\begin{aligned}
E^2_0&\coloneqq\mathsf{AtFml}_2,\\
E^2_{m+1}&\coloneqq E^2_m\cup\{\neg A:A\in E^2_m\}
\cup\{A\circ B:A,B\in E^2_m,\ \circ\in\{\land,\lor\}\}\\
&\quad\cup\{QvA:A\in E^2_m,\ v\in V_0\cup V_1,\ Q\in\{\forall,\exists\}\},\\
\mathsf{Fml}_2&\coloneqq\bigcup_{m<\omega}E^2_m.
\end{aligned}

\mathsf{Arith}:=
\bigcap\left\{\mathcal C\subseteq\mathsf{Fml}_2\ \middle|\
\begin{aligned}
&\mathsf{AtFml}_2\subseteq\mathcal C\\
&\land\forall A,B\in\mathcal C\;
((\neg A)\in\mathcal C\land(A\land B)\in\mathcal C\land(A\lor B)\in\mathcal C)\\
&\land\forall A\in\mathcal C\;\forall v\in V_0\;
((\forall v\,A)\in\mathcal C\land(\exists v\,A)\in\mathcal C)
\end{aligned}\right\}.

\begin{aligned}
\mathrm{CA}_{\mathsf{Arith}}
&:=\{\forall^*\exists X\;\forall n\;
(n\in X\leftrightarrow A(n))\mid A\in\mathsf{Arith},\ n\in V_0,\ X\in V_1\setminus\mathrm{Occ}(A)\},\\
\mathrm{ATR}
&:=\{\forall^*\forall X\;
[\mathrm{WO}(X)\to\exists Y\;\mathrm{Hier}_{A,Z,n}(X,Y)]\mid A\in\mathsf{Arith},\ Z\in V_1,\ n\in V_0,\ X,Y\in V_1\setminus(\mathrm{Occ}(A)\cup\{Z\}),\ X\ne Y\},\\
\mathrm{Ind}_2
&:=\forall X\;([0\in X\land
\forall n\;(n\in X\to \mathsf S(n)\in X)]
\to\forall n\;(n\in X))\quad(X=v_0^1,\ n=v_0^0),\\
\mathrm{ATR}_0
&:=\mathrm{NT}^{-}_2\cup\mathrm{Eql}_2\cup\{\mathrm{Ind}_2\}
\cup\mathrm{CA}_{\mathsf{Arith}}\cup\mathrm{ATR}.
\end{aligned}
